<?php $row=$data['entry'];$states=['pending'=>'Noch nicht verarbeitet','ready'=>'Verarbeitet','partial'=>'Teilweise verarbeitet','unsupported'=>'Format nicht unterstützt','unavailable'=>'Provider nicht verfügbar','error'=>'Auslesefehler','limit'=>'Verarbeitungsgrenze erreicht']; ?>
<div class="page-heading"><div><p class="eyebrow">MEDIUM</p><h1><?= $e($row['name']) ?></h1><p class="lead">Revision <?= $e($row['revision']) ?> · <?= $e($states[$data['media_status']]??'Nicht verfügbar') ?></p></div><a href="<?= $e('/media?'.http_build_query(['space'=>$data['space_id'],'parent'=>$row['parent_id']])) ?>">Zur Medienansicht</a></div>
<section class="panel media-viewer"><?php if ($data['has_preview']): ?><img src="<?= $e('/media/preview?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id'],'revision'=>$row['revision']])) ?>" alt="<?= $e('Vorschau: '.$row['name']) ?>"><?php else: ?><p>Für diesen Dateistand ist keine Vorschau verfügbar.</p><?php endif ?></section>
<p><a href="<?= $e('/media/detail?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id']])) ?>">Ansicht aktualisieren</a> · <a href="<?= $e('/files/detail?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id']])) ?>">Datei verwalten</a><?php if ($data['can_download']): ?> · <a href="<?= $e('/files/download?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id']])) ?>">Original herunterladen</a><?php endif ?></p>
<?php if ($data['media_caps']['process']): ?><details class="panel file-action"><summary>Medienanalyse neu vormerken</summary><div class="disclosure-content"><p>Der Worker verarbeitet den aktuellen Inhaltsstand. Das Original bleibt unverändert.</p><form method="post" action="/media/refresh"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($row['id']) ?>"><input type="hidden" name="revision" value="<?= $e($row['revision']) ?>"><button class="button" type="submit">Medienanalyse vormerken</button></form></div></details><?php endif ?>
<?php if ($data['media_caps']['metadata.read']): ?><section class="panel"><div class="panel-heading"><h2>Ausgelesene Informationen</h2></div><div class="group-list">
<?php foreach ($data['metadata'] as $value): ?><article class="group-row"><div><h3><?= $e($value['label']) ?></h3><p><?= $e($value['normalized']??['not_found'=>'Keine Angabe gefunden','unsupported'=>'Nicht unterstützt','error'=>'Auslesefehler','limit'=>'Feldgrenze erreicht'][$value['status']]??'Keine Angabe') ?></p><details><summary>Quelle und Originalwert</summary><p><?= $e($value['source']) ?> · <?= $e($value['provider']) ?> <?= $e($value['provider_version']) ?> · <?= $e($value['status']) ?></p><p>Originalwert: <?= $e($value['raw']??'Keine Angabe') ?></p></details></div></article><?php endforeach ?>
<?php if ($data['metadata']===[]): ?><p class="empty">Keine lesbaren Analysewerte für diesen Dateistand vorhanden.</p><?php endif ?></div>
<?php if ($data['processed_at']!==null): ?><p class="field-note">Ausgelesen am <?= $e(gmdate('Y-m-d H:i:s',(int)$data['processed_at'])) ?> UTC, angezeigt für Revision <?= $e($row['revision']) ?>.</p><?php endif ?></section><?php endif ?>
<p class="field-note">Die Analyse untersucht ausgewählte EXIF-Felder, Standard-XMP und Photoshop-IPTC in JPEG sowie begrenzte unkomprimierte PNG-Textfelder. Eine KI-Einstufung verwendet ausschließlich unterstützte strukturierte Digital-Source-Type-Angaben. Dateinamen, Programmnamen und freier Prompttext reichen dafür nicht aus. Fehlende Kennzeichnungen belegen keine Entstehung ohne KI. C2PA-Nachweise werden noch nicht untersucht oder validiert.</p>

